import clsx from 'clsx';
import React, { CSSProperties, forwardRef } from 'react';

import { _useProgressAriaProps } from './hooks/useProgressAriaProps.js';
import {
  progressCircleBackgroundCSS,
  progressCircleChildCSS,
  progressCircleContainerCSS,
  progressCircleCSS,
  progressCircleRootCSS,
  ProgressCircleSVGCSS,
} from './ProgressCircle.sty.js';
import { textStyleCSS } from '../../../styles/textStyle.sty.js';
import { _useAriaLabelingProps } from '../../hooks/useAriaLabelingProps.js';
import { _useId } from '../../hooks/useId.js';
import { _useSafeForwardProps } from '../../hooks/useSafeForwardProps.js';
import type { AriaLabelingProps } from '../../types/a11y-props.js';
import type { DataTestId } from '../../types/data-props.js';
import type { DOMProps } from '../../types/dom.js';
import type { RoleVariantType } from '../../types/role-variant.js';
import type { StylingProps } from '../../types/styling-props.js';
import type { WithChildren } from '../../types/with-children.js';

export type ProgressCircleSizeOptionsType = 'small' | 'large';
/** Accepted properties for ProgressCircle */
export interface ProgressCircleProps
  extends WithChildren,
    DOMProps,
    AriaLabelingProps,
    StylingProps,
    DataTestId {
  /**
   * The current value.
   * @defaultValue 'indeterminate'
   */
  value?: number | 'indeterminate';
  /**
   * The smallest allowed value.
   * @defaultValue 0
   */
  min?: number;
  /**
   * The maximum allowed value.
   * @defaultValue 100
   */
  max?: number;
  /**
   * Controls the size of the rendered progress.
   * @defaultValue 'large'
   */
  size?: ProgressCircleSizeOptionsType;
  /**
   * Controls the appearance of the progress.
   * @defaultValue 'primary'
   */
  variant?: RoleVariantType;

  /**
   * The aria-valuetext attribute defines the human-readable text alternative of aria-valuenow for a range widget.
   * Default the value as percentage will be provided. If the value is not a percentage please provide the aria-valuetext.
   * https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Attributes/aria-valuetext
   * @defaultValue the value of the progress as percentage.
   */
  'aria-valuetext'?: string;
}

const progressCircleSizes = {
  small: 20,
  large: 40,
};
const progressCircleThickness = 5;

/** The `ProgressCircle` component is used to indicate the progress or completion status of a task or process. */
export const ProgressCircle = forwardRef<HTMLDivElement, ProgressCircleProps>(
  (props, forwardedRef) => {
    const {
      value: originalValue,
      min = 0,
      max = 100,
      size = 'large',
      variant = 'primary',
      children,
      id: propId,
      'aria-valuetext': ariaValuetext,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: ProgressCircleProps = props;

    const { value, isIndeterminate, progressAriaProps } = _useProgressAriaProps(
      originalValue,
      min,
      max,
      ariaValuetext,
    );

    const ariaLabelingProps = _useAriaLabelingProps(remainingProps);
    const forwardProps = _useSafeForwardProps(
      remainingProps,
      ariaLabelingProps,
    );

    const generatedId = _useId({ prefix: 'progress-circle' });
    const id = propId ?? generatedId;

    const circleStyles: CSSProperties = {};
    const rootProps = {};

    if (!isIndeterminate && value !== undefined) {
      const circumference =
        2 *
        Math.PI *
        ((progressCircleSizes[size] - progressCircleThickness) / 2);
      circleStyles['strokeDasharray'] = circumference.toFixed(3);
      const dashOffset = Number(
        (((max - value) / max) * circumference).toFixed(3),
      );
      circleStyles['strokeDashoffset'] = `${
        dashOffset >= 0 ? dashOffset : 0
      }px`;
    }

    if (
      !children &&
      !ariaLabelingProps['aria-label'] &&
      !ariaLabelingProps['aria-labelledby']
    ) {
      process.env.NODE_ENV === 'development' &&
        // eslint-disable-next-line no-console
        console.warn(
          'If no label is provided please make sure to provide an aria label on your progressCircle element.',
        );
    }

    return (
      <div
        data-testid={dataTestId}
        ref={forwardedRef}
        className={clsx(
          consumerClassName,
          progressCircleContainerCSS({ size }),
        )}
        style={consumerStyle}
        {...forwardProps}
      >
        <span
          id={id}
          className={clsx(
            consumerClassName,
            progressCircleRootCSS({ variant }),
          )}
          style={{
            height: `${progressCircleSizes[size]}px`,
            width: `${progressCircleSizes[size]}px`,
          }}
          {...ariaLabelingProps}
          {...progressAriaProps}
          {...rootProps}
        >
          <svg
            className={ProgressCircleSVGCSS}
            viewBox={`0 0 ${progressCircleSizes[size]} ${progressCircleSizes[size]}`}
            width="100%"
            height="100%"
          >
            <circle
              fill="none"
              className={progressCircleBackgroundCSS({ variant })}
              cx={progressCircleSizes[size] / 2}
              cy={progressCircleSizes[size] / 2}
              r={(progressCircleSizes[size] - progressCircleThickness) / 2}
              strokeWidth={progressCircleThickness}
            />
            <circle
              style={circleStyles}
              className={progressCircleCSS({ indeterminate: isIndeterminate })}
              fill="none"
              pathLength={
                isIndeterminate ? 360 : circleStyles['strokeDasharray']
              }
              cx={progressCircleSizes[size] / 2}
              cy={progressCircleSizes[size] / 2}
              r={(progressCircleSizes[size] - progressCircleThickness) / 2}
              strokeWidth={progressCircleThickness}
            />
          </svg>
        </span>
        {children && (
          <label
            className={clsx(
              progressCircleChildCSS({ variant }),
              textStyleCSS({ textStyle: size === 'small' ? 'small' : 'base' }),
            )}
            htmlFor={id}
          >
            {children}
          </label>
        )}
      </div>
    );
  },
);

(
  ProgressCircle as typeof ProgressCircle & { displayName: string }
).displayName = 'ProgressCircle';
